using static StrataLint.Scribe.DefinitionDsl;
using static StrataLint.Scribe.FormulaDsl;
using F = StrataLint.Scribe.FormulaDsl;

namespace StrataLint.Scribe.Blueprint.D5.S3.Combinatorics.Graph.LinearForests;

internal sealed class DirectedForestCompletionDocument : IScribeDocumentDefinition
{
    private const string Prefix = "D5/S3/Combinatorics/Graph/LinearForests/DirectedForestCompletion.";
    private static readonly LibraryNoteRef Source =
        LibraryNoteRef.Create("D5/L/PermutationPatterns/tsaban2003permutation");
    private static Formula Name(string s) => new Formula.NamedConstant(FormulaIdentifier.Create(s));
    private static Formula All(string n, Formula t, Formula b) =>
        new Formula.Bind(FormulaQuantifier.ForAll, FormulaIdentifier.Create(n), t, b);
    private static Formula Ex(string n, Formula t, Formula b) =>
        new Formula.Bind(FormulaQuantifier.Exists, FormulaIdentifier.Create(n), t, b);
    private static Formula And(Formula a, Formula b) => new Formula.Logic(a, FormulaLogicOperator.And, b);
    private static Formula Imp(Formula a, Formula b) => new Formula.Logic(a, FormulaLogicOperator.Implies, b);
    private static Formula Eq(Formula a, Formula b) => new Formula.Relation(a, FormulaRelationOperator.Equal, b);
    private static Formula Le(Formula a, Formula b) => new Formula.Relation(a, FormulaRelationOperator.LessThanOrEqual, b);
    private static Formula C(string s) => Call(s, F.Id("E"));
    private static Formula At(string f, Formula x) => Call("apply", F.Id(f), x);
    private static Formula Part(string f) => All("A", C("Component"),
        Eq(Call("component", F.Id("E"), Call("value", At(f, F.Id("A")))), F.Id("A")));
    private static Formula Endpoint() => All("sigma", C("CycleCompletion"),
        All("A", C("Component"), Eq(
            Call("apply", Call("value", F.Id("sigma")), Call("value", At("q", F.Id("A")))),
            Call("value", At("h", Call("apply", Call("value", At("Phi", F.Id("sigma"))), F.Id("A")))))));
    private static Formula CountAndLaw() => And(
        Eq(Call("card", C("CycleCompletion")),
            Call("factorial", Call("sub", Call("card", C("Component")), D(1)))),
        Call("UniformCompletionLaw", F.Id("E"), F.Id("q"), F.Id("h"), F.Id("Phi")));
    private static Formula Conclusion() =>
        Ex("q", Call("Equiv", C("Component"), C("Tail")),
        Ex("h", Call("Equiv", C("Component"), C("Head")),
        Ex("Phi", Call("Equiv", C("CycleCompletion"), Call("FullCycle", C("Component"))),
            And(Part("q"), And(Part("h"), And(Endpoint(),
                And(Call("Nonempty", C("CycleCompletion")), CountAndLaw())))))));
    private static Formula Statement() => All("V", Name("Type"),
        Seq(OpenBracket, Call("Finite", F.Id("V")), CloseBracket, Comma, Sp,
            All("E", Call("Relation", F.Id("V")),
                Imp(And(C("RightUnique"), And(C("LeftUnique"),
                    And(C("Acyclic"), Le(D(2), Call("card", C("Component")))))), Conclusion()))));

    public DocumentDefinition Create() => DocumentDefinition.Create(ScribeNode.Create(
        "A finite directed linear forest on its full original carrier has an endpoint-compatible equivalence between actual full-cycle permutation completions and actual full cycles of its weak components, with the exact conditional uniform law and a completion count factorial in the number of components, and the exact raw endpoint marginals.",
        H("Directed forest completion"),
        Blocks(Describe.Lean(DescribeId.Create("completion"),
            DeclarationHandle.Create(Prefix + "directed_forest_completion"),
            H("Actual components and exhaustive cycle contraction"),
            StatementSource.FromAuthor(Disp(Statement())),
            AssessedProvenance.FromLiterature(Source),
            Blocks(
                Paragraph(Text("Let V be any finite labelled type and E a binary relation on V. RightUnique means that E(x,y) and E(x,z) imply y=z. LeftUnique means that E(y,x) and E(z,x) imply y=z. Acyclic means that there is no nonempty directed E-path from a vertex to itself, expressed as the irreflexivity of Relation.TransGen E. Component(E) is the quotient of all of V by Relation.EqvGen E, the equivalence relation generated by E. Thus these are the true weak components, and every isolated vertex is a singleton component. Assume c=card(Component(E)) is at least two.")),
                Paragraph(Text("Head(E) is the subtype of vertices with no incoming E-edge; Tail(E) is the subtype with no outgoing E-edge. The result supplies equivalences h:Component(E) to Head(E) and q:Component(E) to Tail(E) whose values belong to the specified component. Consequently each actual component has a unique head and a unique tail. For a singleton component both underlying vertices coincide. In the formula, component(E,x) denotes the class of x and value denotes the underlying value of a subtype.")),
                Paragraph(Text("FullCycle(W) consists of actual permutations rho of W satisfying rho.IsCycleOn univ. CycleCompletion(E) consists of actual permutations sigma of V satisfying both sigma.IsCycleOn univ and sigma(x)=y for every E(x,y). These sets are defined independently of any constructor. The equivalence Phi maps exactly CycleCompletion(E) onto FullCycle(Component(E)), and for every sigma and component A its endpoint equation is sigma(q(A))=h(Phi(sigma)(A)). The completion set is nonempty and has cardinality (c-1)!. Full-cycle completions on two vertices and c=2 are included; no SimpleGraph cycle convention is used.")),
                Paragraph(Text("First split vertices according to whether an outgoing or incoming E-edge exists. The original relation gives an equivalence between those two occupied subtypes. Mathlib's subtypeCongr combines it with any tail-to-head equivalence. Conversely, injectivity of every actual extension forces tails into heads, and its inverse shows that every head is reached. The two constructions are inverse on the entire original carrier.")),
                Paragraph(Text("Termination and uniqueness of successors identify a terminal vertex in each actual weak component; applying the same construction to the reversed relation identifies its head. A directed E-path from a head to its component's tail gives a positive first-return segment to the actual head set under every extension. Its intermediate vertices have an incoming E-edge and cannot be heads. The next vertex is exactly the connector head. FiniteEndpointPairing.same_cycle_of_first_visit supplies the orbit equivalence. Every original interior vertex lies in the same extension orbit as its component head, so the marked orbit comparison is equivalent to the full-carrier orbit comparison.")),
                Paragraph(Text("The count uses Mathlib's card_of_cycleType_singleton after the full-support cycle correspondence. The small normalization helper is adapted from leanprover/cslib, and the full-support correspondence is adapted from Xingchen Liu and Xiangyu Ye; the source attributions and licenses are preserved in the Lean source and Library/PermutationPatterns/liuye2026cyclesupport.md.")),
                Paragraph(Text("The cited classical source treats acyclic partial permutation graphs, isolated components, their extrema, all full-cycle extensions and the uniform choice among other components in Section 1, Lemmas 1.1–1.3, Definition 1.4 and Lemma 1.5 on pages 107–109. This is mathematical lineage, not a Lean dependency or a literature priority claim.")),
                Paragraph(Text("UniformCompletionLaw(E,q,h,Phi) asserts that there exist probability mass functions mu0 on FullCycle(V) and muE on CycleCompletion(E). Every mu0 point mass is the reciprocal of card(FullCycle(V)), and every muE point mass is the reciprocal of card(CycleCompletion(E)). The extension event inside FullCycle(V) has a point in the support of mu0, and filtering and renormalizing mu0 by that event equals the pushforward of muE along the inclusion sigma maps to its actual full-cycle permutation. Every point mass of muE.map(Phi) is the reciprocal of card(FullCycle(Component(E))). For the same muE witness, its pushforward by sigma maps to sigma(q(A)), evaluated at the actual vertex h(B), is zero when A=B and the reciprocal of c-1 otherwise. Thus the event is nonnull, conditioning gives the uniform completion law, and Phi pushes it to the uniform law on actual component cycles. The raw event bridge uses the endpoint equation and injectivity of h: sigma(q(A))=h(B) if and only if Phi(sigma)(A)=B. Conjugation by a transposition fixing A makes all other component images equiprobable; a full cycle fixes no component and PMF normalization makes each remaining mass 1/(c-1). The proof reuses the repository finite uniform PMF, Mathlib PMF.map and PMF.filter, and finite sum identities.")),
                Paragraph(Text("This result establishes the structural equivalence, nonemptiness, exact cardinality, conditioning, uniform pushforward and the individual raw endpoint probabilities zero and 1/(c-1), including c=2. It gives no undirected orientation multiplicity, alternating-cycle law, adaptive transcript or random-label conditioning, query bound, or EXIT probability. Those statements require their own distribution and correspondence proofs."))),
            DescribeRole.Theorem)), []));
}
